 @timeit
 def solveit(case):
     ns = case["Naomi"]
     ks = case["Ken"]

     # calculate deceptive war
     nsmin = 0
     ksmin = 0

     dwpoints = 0
     while nsmin < len(ns):
         if ns[nsmin] > ks[ksmin]:
             ksmin += 1
             dwpoints += 1 
         nsmin += 1

     # calculate regular war
     nsmax = len(ns) - 1
     ksmin = 0

     wpoints = 0
     while len(ks) >= ksmin + 1:
         print ns, ks, nsmax, ksmin
         if ns[nsmax] > ks[-1]:
             ksmin += 1
             wpoints += 1
         else:
             m = ksmin
             for i in xrange(len(ks)-1, ksmin-1, -1):
                 if ks[i] < ns[nsmax]:
                     m = i + 1
                     break
             del ks[m]
         nsmax -= 1

     return str(dwpoints) + " " + str(wpoints) 


