def test_win(M, c):
     N = len(M)
     def yielder():
         for row in M:
             yield row, 'row'
         for i in xrange(N):
             yield [row[i] for row in M], 'col'
         yield [M[i][i] for i in xrange(N)], 'd1'
         yield [M[i][N-i-1] for i in xrange(N)], 'd2'
     for lst, typ in yielder():
         if all(l == c or l == 'T' for l in lst):
             #print "won at %s %s" % (lst, typ)
             return True
     return False

