 def is_palindrome(n):
     n = str(n)
     return n == n[::-1]

 def solve(A, B):
     # Loop through palindromic numbers and check that their squares are palindromes.
     count = 0
     for n in palindromes():
         square = n**2
         if square > B:
             break
         if square >= A and is_palindrome(square):
             count += 1
     return count

