def find_recycled(n, b):
 	ns = str(n)
 	reclist = []
 	for i in xrange(1, len(ns), 1):
 		nrec = ns[i:len(ns)] + ns[0:i]
 		if nrec[0] != "0":
 			nrec = eval(nrec)
 			if nrec <= b and nrec > n and (n, nrec) not in reclist:
 				reclist.append((n,nrec))
 	return len(reclist)

